function AoDJPAddonProbe_applyLabels() {
   AoDJPAddonProbe_applyMapLabels();
   if (isObject(CP_weight_max)) CP_weight_max.setText("1ポンド");
   if (isObject(CP_weight_sel)) CP_weight_sel.setText("0.5ポンド");
   if (isObject(CP_weight_min)) CP_weight_min.setText("0ポンド");
   if (isObject(CrS_localization_caption)) CrS_localization_caption.setText("<language>翻訳チーム：");
   if (isObject(IS_button_Apply)) IS_button_Apply.setText("適用");
   if (isObject(IS_button_Reset)) IS_button_Reset.setText("リセット");
   if (isObject(MS_item_example)) MS_item_example.setText("サンプル地点");
   if (isObject(PG_HelpText_01)) PG_HelpText_01.setText("操作方法：\n- 右クリックで移動。\n- 左クリックで対象に働きかける。\n- マウスの中央ボタンを押しながら動かすとカメラが回転。\n- マウスホイールで拡大・縮小。\n- W、A、S、Dでカメラを移動。\n- Q、Eでカメラを回転。\n- Rでクロスボウを再装填。\n- 各ボタンにカーソルを合わせると説明を表示。\n\nF1でゲームのヘルプを表示。");
   if (isObject(PG_HelpText_02)) PG_HelpText_02.setText("戦闘時の操作：\n- マスを右クリックして移動。\n- 左クリックで攻撃。\n- 武器スロットを右クリックして攻撃方法を選択。\n\nF1でゲームのヘルプを表示。");
   if (isObject(PG_combatHInt_defence_rating_header)) PG_combatHInt_defence_rating_header.setText("防御値");
   if (isObject(PG_combatHint_attack_rating_header)) PG_combatHint_attack_rating_header.setText("攻撃値");
   if (isObject(TO_TurnOffCheckbox)) TO_TurnOffCheckbox.setText("今後表示しない");
}
